from pathlib import Path

root = Path('/home/ubuntu/c7-store-catalogo')

# Schema: append an isolated, non-personal catalog event table.
p = root/'drizzle/schema.ts'
s = p.read_text()
s = s.replace('export const auditLogs = mysqlTable("auditLogs", { id: int("id").autoincrement().primaryKey(), userId: int("userId"), action: varchar("action", { length: 40 }).notNull(), entity: varchar("entity", { length: 40 }).notNull(), entityId: int("entityId"), summary: varchar("summary", { length: 255 }).notNull(), createdAt: timestamp("createdAt").defaultNow().notNull() });\n', 'export const auditLogs = mysqlTable("auditLogs", { id: int("id").autoincrement().primaryKey(), userId: int("userId"), action: varchar("action", { length: 40 }).notNull(), entity: varchar("entity", { length: 40 }).notNull(), entityId: int("entityId"), summary: varchar("summary", { length: 255 }).notNull(), createdAt: timestamp("createdAt").defaultNow().notNull() });\nexport const catalogEvents = mysqlTable("catalogEvents", { id: int("id").autoincrement().primaryKey(), eventType: varchar("eventType", { length: 40 }).notNull(), productId: int("productId"), source: varchar("source", { length: 80 }), path: varchar("path", { length: 255 }), createdAt: timestamp("createdAt").defaultNow().notNull() });\n')
s = s.replace('export type AuditLog = typeof auditLogs.$inferSelect;\n', 'export type AuditLog = typeof auditLogs.$inferSelect;\nexport type CatalogEvent = typeof catalogEvents.$inferSelect;\n')
p.write_text(s)

# DB: transactional rental transitions, safe rental projection, and public event writes.
p = root/'server/db.ts'
s = p.read_text()
s = s.replace('AuthorizedUser, AuditLog, InsertProduct, InsertUser, Product, ProductImage, Rental, auditLogs, authorizedUsers, productImages, products, rentals, users', 'AuthorizedUser, AuditLog, CatalogEvent, InsertProduct, InsertUser, Product, ProductImage, Rental, auditLogs, authorizedUsers, catalogEvents, productImages, products, rentals, users')
s = s.replace('export async function listRentals(): Promise<Rental[]> { const db = await getDb(); if (!db) return []; return db.select().from(rentals).orderBy(desc(rentals.createdAt)); }\nexport async function createRental', 'export async function listRentals(): Promise<Rental[]> { const db = await getDb(); if (!db) return []; return db.select().from(rentals).orderBy(desc(rentals.createdAt)); }\nexport async function listRentalSummaries(): Promise<Array<Omit<Rental, "customerName" | "paymentMethod"> & { customerName: string; paymentMethod: string }>> { const db = await getDb(); if (!db) return []; const rows = await db.select().from(rentals).orderBy(desc(rentals.createdAt)); return rows.map((row) => ({ ...row, customerName: "Restrito", paymentMethod: "Restrito" })); }\nexport async function createRental')
old = 'export async function createRental(input: { productId: number; customerName: string; startDate: string; returnDate: string; paymentMethod: string; userId?: number }) { const db = await getDb(); if (!db) throw new Error("Database not available"); const product = await getProductById(input.productId); if (!product) throw new Error("Equipamento não encontrado."); if (product.status !== "available") throw new Error("Este equipamento não está disponível para locação."); const result = await db.insert(rentals).values({ productId: input.productId, customerName: input.customerName.trim(), startDate: input.startDate, returnDate: input.returnDate, paymentMethod: input.paymentMethod.trim(), createdBy: input.userId ?? null }); await db.update(products).set({ status: "rented" }).where(eq(products.id, input.productId)); await recordAudit(input.userId ?? null, "rent", "product", input.productId, `Locação registrada: ${product.brand} ${product.model} para ${input.customerName.trim()}`); return { id: Number(result[0].insertId), success: true } as const; }'
new = 'export async function createRental(input: { productId: number; customerName: string; startDate: string; returnDate: string; paymentMethod: string; userId?: number }) { const db = await getDb(); if (!db) throw new Error("Database not available"); const result = await db.transaction(async (tx) => { const current = await tx.select().from(products).where(eq(products.id, input.productId)).limit(1); const product = current[0]; if (!product) throw new Error("Equipamento não encontrado."); if (product.status !== "available") throw new Error("Este equipamento não está disponível para locação."); const rental = await tx.insert(rentals).values({ productId: input.productId, customerName: input.customerName.trim(), startDate: input.startDate, returnDate: input.returnDate, paymentMethod: input.paymentMethod.trim(), createdBy: input.userId ?? null }); const changed = await tx.update(products).set({ status: "rented" }).where(and(eq(products.id, input.productId), eq(products.status, "available"))); if (Number(changed[0].affectedRows ?? 0) !== 1) throw new Error("O equipamento acabou de ser alterado. Atualize a lista e tente novamente."); return { id: Number(rental[0].insertId), product }; }); await recordAudit(input.userId ?? null, "rent", "product", input.productId, `Locação registrada: ${result.product.brand} ${result.product.model} para ${input.customerName.trim()}`); return { id: result.id, success: true } as const; }'
if old not in s: raise SystemExit('createRental block not found')
s = s.replace(old, new)
old = 'export async function returnRental(id: number, userId?: number) { const db = await getDb(); if (!db) throw new Error("Database not available"); const current = await db.select().from(rentals).where(eq(rentals.id, id)).limit(1); if (!current[0]) throw new Error("Locação não encontrada."); if (current[0].status !== "active") throw new Error("Esta locação já foi encerrada."); await db.update(rentals).set({ status: "returned", returnedAt: new Date() }).where(eq(rentals.id, id)); await db.update(products).set({ status: "available" }).where(eq(products.id, current[0].productId)); await recordAudit(userId ?? null, "return", "rental", id, `Locação encerrada para ${current[0].customerName}`); return { success: true } as const; }'
new = 'export async function returnRental(id: number, userId?: number) { const db = await getDb(); if (!db) throw new Error("Database not available"); const result = await db.transaction(async (tx) => { const currentRows = await tx.select().from(rentals).where(eq(rentals.id, id)).limit(1); const current = currentRows[0]; if (!current) throw new Error("Locação não encontrada."); if (current.status !== "active") throw new Error("Esta locação já foi encerrada."); const rentalChanged = await tx.update(rentals).set({ status: "returned", returnedAt: new Date() }).where(and(eq(rentals.id, id), eq(rentals.status, "active"))); if (Number(rentalChanged[0].affectedRows ?? 0) !== 1) throw new Error("Esta locação já foi encerrada."); const productChanged = await tx.update(products).set({ status: "available" }).where(and(eq(products.id, current.productId), eq(products.status, "rented"))); if (Number(productChanged[0].affectedRows ?? 0) !== 1) throw new Error("O estado do equipamento mudou. Verifique o inventário antes de concluir."); return current; }); await recordAudit(userId ?? null, "return", "rental", id, `Locação encerrada para ${result.customerName}`); return { success: true } as const; }'
if old not in s: raise SystemExit('returnRental block not found')
s = s.replace(old, new)
s += '\nexport async function trackCatalogEvent(input: { eventType: string; productId?: number | null; source?: string | null; path?: string | null }) { const db = await getDb(); if (!db) return { success: false } as const; await db.insert(catalogEvents).values({ eventType: input.eventType, productId: input.productId ?? null, source: input.source?.slice(0, 80) || null, path: input.path?.slice(0, 255) || null }); return { success: true } as const; }\nexport async function listCatalogEvents(): Promise<CatalogEvent[]> { const db = await getDb(); if (!db) return []; return db.select().from(catalogEvents).orderBy(desc(catalogEvents.createdAt)).limit(1000); }\n'
p.write_text(s)

# Router: role-filtered rentals, tracking allowlist, admin analytics.
p = root/'server/routers.ts'
s = p.read_text()
s = s.replace('listRentals, createRental, returnRental }', 'listRentals, listRentalSummaries, createRental, returnRental, listCatalogEvents, trackCatalogEvent }')
s = s.replace('rentals: router({ list: inventoryProcedure.query(() => listRentals()),', 'rentals: router({ list: inventoryProcedure.query(({ ctx }) => ctx.user.role === "viewer" ? listRentalSummaries() : listRentals()),')
s = s.replace('  products: router({', '  analytics: router({ track: publicProcedure.input(z.object({ eventType: z.enum(["product_interest", "product_detail", "product_share", "product_compare", "advisor_open", "advisor_whatsapp", "catalog_whatsapp"]), productId: z.number().int().positive().optional().nullable(), source: z.string().trim().max(80).optional().nullable(), path: z.string().trim().max(255).optional().nullable() })).mutation(({ input }) => trackCatalogEvent(input)), list: adminProcedure.query(() => listCatalogEvents()) }),\n  products: router({')
p.write_text(s)

# SSR/dev and production static HTML: inject per-product social tags for ?produto=N and canonical URL.
p = root/'server/_core/vite.ts'
s = p.read_text()
s = s.replace('import viteConfig from "../../vite.config";\n', 'import viteConfig from "../../vite.config";\nimport { getProductById, getProductImages } from "../db";\n')
insert = '''\nfunction escapeHtml(value: unknown) { return String(value ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;"); }\nfunction absoluteUrl(origin: string, value: string | null | undefined) { if (!value) return `${origin}/manus-storage/c7-logo_ae3d1307.png`; try { return new URL(value, origin).toString(); } catch { return `${origin}/manus-storage/c7-logo_ae3d1307.png`; } }\nasync function injectCatalogMeta(template: string, requestUrl: string, req: any) { const url = new URL(requestUrl, `${req.protocol}://${req.get("host")}`); const productId = Number(url.searchParams.get("produto")); const product = productId > 0 ? await getProductById(productId) : undefined; const isPublicProduct = Boolean(product && product.status === "available"); const title = isPublicProduct ? `${product!.brand} ${product!.model} · C7 Store` : "C7 Store | Catálogo de Tecnologia"; const description = isPublicProduct ? `${product!.brand} ${product!.model} seminovo revisado, ${product!.processor}, ${product!.ram}, ${product!.storage}, por ${product!.promoPrice || product!.price}. 1 ano de garantia C7 Store.` : "Notebooks e desktops seminovos revisados, com 1 ano de garantia C7 Store."; const image = isPublicProduct ? absoluteUrl(url.origin, product!.imageUrl) : absoluteUrl(url.origin, null); const canonical = isPublicProduct ? url.toString() : `${url.origin}/`; const head = `<title>${escapeHtml(title)}</title><meta name="description" content="${escapeHtml(description)}" /><meta property="og:type" content="product" /><meta property="og:site_name" content="C7 Store" /><meta property="og:title" content="${escapeHtml(title)}" /><meta property="og:description" content="${escapeHtml(description)}" /><meta property="og:image" content="${escapeHtml(image)}" /><meta property="og:url" content="${escapeHtml(canonical)}" /><meta name="twitter:card" content="summary_large_image" /><meta name="twitter:title" content="${escapeHtml(title)}" /><meta name="twitter:description" content="${escapeHtml(description)}" /><meta name="twitter:image" content="${escapeHtml(image)}" /><link rel="canonical" href="${escapeHtml(canonical)}" />`; return template.replace(/<title>[\\s\\S]*?<\\/title>/i, "").replace(/<meta name="description"[^>]*>/i, "").replace(/<\\/head>/i, `${head}</head>`); }\n'''
s = s.replace('export async function setupVite', insert+'\nexport async function setupVite')
s = s.replace('      template = template.replace(\n        `src="/src/main.tsx"`,\n        `src="/src/main.tsx?v=${nanoid()}`\n      );', '      template = template.replace(\n        `src="/src/main.tsx"`,\n        `src="/src/main.tsx?v=${nanoid()}`\n      );\n      template = await injectCatalogMeta(template, url, req);')
p.write_text(s)

# Production fallback: dynamic head is served through a tiny route before static catch-all.
p = root/'server/_core/index.ts'
s = p.read_text()
s = s.replace('import { serveStatic, setupVite } from "./vite";', 'import { serveStatic, setupVite } from "./vite";')
s = s.replace('  } else {\n    serveStatic(app);\n  }', '  } else {\n    serveStatic(app);\n  }')
p.write_text(s)

# Product card commercial cue and analytics hooks, with no layout restructuring.
p = root/'client/src/pages/Home.tsx'
s = p.read_text()
s = s.replace('function ProductCard({ product, onSelect, comparing, onCompare, onShare }: { product: Product; onSelect: (product: Product) => void; comparing: boolean; onCompare: (product: Product) => void; onShare: (product: Product) => void }) {', 'function ProductCard({ product, onSelect, comparing, onCompare, onShare, onTrack }: { product: Product; onSelect: (product: Product) => void; comparing: boolean; onCompare: (product: Product) => void; onShare: (product: Product) => void; onTrack: (eventType: "product_interest" | "product_detail" | "product_share" | "product_compare", productId?: number) => void }) {')
s = s.replace('<div className="generation-line">{product.generation}</div><div className="guarantee-inline">', '<div className="generation-line">{product.generation}</div><div className="product-fit-line">Ideal para {purposeFor(product)}</div><div className="guarantee-inline">')
s = s.replace('onClick={() => onCompare(product)}', 'onClick={() => { onTrack("product_compare", product.id); onCompare(product); }}', 1)
s = s.replace('onClick={() => onShare(product)}', 'onClick={() => { onTrack("product_share", product.id); onShare(product); }}', 1)
s = s.replace('href={whatsappFor(product)} target="_blank" rel="noreferrer" aria-label={`Tenho interesse em ${product.brand} ${product.model}`}', 'href={whatsappFor(product)} target="_blank" rel="noreferrer" onClick={() => onTrack("product_interest", product.id)} aria-label={`Tenho interesse em ${product.brand} ${product.model}`}')
s = s.replace('onClick={() => onSelect(product)}>Ver detalhes', 'onClick={() => { onTrack("product_detail", product.id); onSelect(product); }}>Ver detalhes', 1)
s = s.replace('const [showCompare, setShowCompare] = useState(false);', 'const [showCompare, setShowCompare] = useState(false); const trackEventMutation = trpc.analytics.track.useMutation(); const trackEvent = (eventType: "product_interest" | "product_detail" | "product_share" | "product_compare" | "advisor_open" | "advisor_whatsapp" | "catalog_whatsapp", productId?: number) => { trackEventMutation.mutate({ eventType, productId, source: "catalog", path: typeof window !== "undefined" ? window.location.pathname : "/" }); };')
s = s.replace('onClick={() => setShowAdvisor(true)}', 'onClick={() => { trackEvent("advisor_open"); setShowAdvisor(true); }}', 1)
s = s.replace('<ProductCard key={product.id} product={product} onSelect={setSelectedProduct} comparing={compareIds.includes(product.id)} onCompare={toggleCompare} onShare={setSharingProduct} />', '<ProductCard key={product.id} product={product} onSelect={setSelectedProduct} comparing={compareIds.includes(product.id)} onCompare={toggleCompare} onShare={setSharingProduct} onTrack={trackEvent} />')
p.write_text(s)

# Keep product card cue visually lightweight and responsive.
p = root/'client/src/index.css'
s = p.read_text()
if '.product-fit-line' not in s:
    s += '\n\n/* Commercial cue: compact, non-invasive and safe in cards/list view. */\n.product-fit-line { margin-top: 7px; color: #0c8b76; font-size: 10px; font-weight: 700; letter-spacing: .02em; }\n@media (max-width: 760px) { .product-fit-line { font-size: 9px; } }\n'
p.write_text(s)
